pub fn second_edition(title: String, year: u32) -> ((String, u32), (String, u32)) {
    let mut second = title.clone();
    second.push_str(" (2nd ed.)");
    ((title, year), (second, year + 1))
}

run.main:
fn main() {
    let ((mut original,y1),(mut revised,y2))=second_edition(String::from("東京"),2024); revised.push('!'); assert_eq!(original,"東京"); original.push('?'); assert_eq!(original,"東京?"); assert_eq!(revised,"東京 (2nd ed.)!"); assert_eq!((y1,y2),(2024,2025));
}

fn main() {
    let year=7_u32; let ((a,y1),(b,y2))=second_edition(String::from("é"),year); assert_eq!(year,7); assert_eq!((y1,y2),(7,8)); assert_eq!(a,"é"); assert_eq!(b,"é (2nd ed.)");
}

